import{_ as s,o as i,c as e,a3 as a}from"./chunks/framework.d6OaePA7.js";const u=JSON.parse('{"title":"物理机安装Linux同时实现内网穿透","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://scattter.github.io/pages/explore/others/%E7%89%A9%E7%90%86%E6%9C%BA%E5%AE%89%E8%A3%85Linux%E5%90%8C%E6%97%B6%E5%AE%9E%E7%8E%B0%E5%86%85%E7%BD%91%E7%A9%BF%E9%80%8F.html"}]]},"headers":[],"relativePath":"pages/explore/others/物理机安装Linux同时实现内网穿透.md","filePath":"pages/explore/others/物理机安装Linux同时实现内网穿透.md","lastUpdated":1693917276000}'),t={name:"pages/explore/others/物理机安装Linux同时实现内网穿透.md"};function n(o,l,r,p,d,c){return i(),e("div",null,[...l[0]||(l[0]=[a(`<h1 id="物理机安装linux同时实现内网穿透" tabindex="-1">物理机安装Linux同时实现内网穿透 <a class="header-anchor" href="#物理机安装linux同时实现内网穿透" aria-label="Permalink to &quot;物理机安装Linux同时实现内网穿透&quot;">​</a></h1><p>去年换工作(2021)后, 由于一直对前公司的mac系统念念不忘, 所以自己在网上买了一个小主机, 搭建了一个黑苹果玩了玩, 后面因为新公司有笔记本电脑, 然后因为小主机确实不方便实用, 所以自己也买了新电脑, 这个主机就空置在这里了.</p><p>最近想着该电脑放着也是放着, 而正好现在自己搞了一个项目, 需要部署很占用内存的gitlab, 所以就想着先将其做成一个服务器, 在上面跑一些自己的服务利用起来, 后面有自己房子了再说搭建软路由的事情.</p><blockquote><p>本文内容参考UP主: <strong><a href="https://space.bilibili.com/326987957" target="_blank" rel="noreferrer">零夏的天空 </a></strong> 视频实战整理而成</p><p>其他参考资料</p><p><a href="https://blog.csdn.net/klo220/article/details/114251913" target="_blank" rel="noreferrer">https://blog.csdn.net/klo220/article/details/114251913</a></p><p><a href="https://learnku.com/articles/39879" target="_blank" rel="noreferrer">https://learnku.com/articles/39879</a></p><p><a href="https://lxnchan.cn/cf-tunnel.html" target="_blank" rel="noreferrer">https://lxnchan.cn/cf-tunnel.html</a></p><p><a href="https://www.modb.pro/db/523813" target="_blank" rel="noreferrer">https://www.modb.pro/db/523813</a></p></blockquote><h2 id="_1-安装centos" tabindex="-1">1. 安装Centos <a class="header-anchor" href="#_1-安装centos" aria-label="Permalink to &quot;1. 安装Centos&quot;">​</a></h2><blockquote><p>自己搭建系统后要注意看22端口是否正常开启使用, 没有正常开启会影响后面的ssh连接</p></blockquote><ol><li>下载系统</li></ol><p>镜像可以去网上搜索, 阿里云的和清华镜像都可以, 我自己尝试如果使用5G热点(4G套餐)下载清华镜像可以达到恐怖的32M/s的速度. 以<code>CentOS-7-x86_64-DVD-2207-02</code> 为例, 我下载下来只用了两分钟</p><ul><li>清华源 <ul><li><a href="https://mirrors.tuna.tsinghua.edu.cn/centos/7/isos/x86_64/" target="_blank" rel="noreferrer">https://mirrors.tuna.tsinghua.edu.cn/centos/7/isos/x86_64/</a></li></ul></li><li>阿里云源 <ul><li><a href="https://mirrors.aliyun.com/centos/7/isos/x86_64/" target="_blank" rel="noreferrer">https://mirrors.aliyun.com/centos/7/isos/x86_64/</a></li></ul></li></ul><ol start="2"><li>制作启动盘</li></ol><p>许多人推荐32G以上大小U盘, 实测使用16G也能正常安装, 又因为有windows和mac os不同系统, 所以分为两种制作方法</p><ul><li><p>windows</p><ul><li>使用<code>UrtaISO</code>软件进行操作, 这里的详细操作可以直接搜索, GUI式操作</li></ul></li><li><p>mac os (使用命令行进行操作)</p><ul><li><p>首先使用<code>diskutil list</code>命令查看分区, 确定自己的U盘是哪个, 如<code>/dev/disk4</code></p></li><li><p>确定后使用命令 <code>diskutil unmountDisk</code> 卸载 U 盘的挂载</p></li><li><p>进入到 iso 文件所在的目录，使用命令 <code>dd</code> 把 CentOS ISO 写入到 U 盘, 比如我将镜像下载到桌面上, name执行命令就是<code>/Users/zhangke/Desktop</code> 和 <code>sudo dd if=CentOS-7-x86_64-DVD-2207-02.iso of=/dev/rdisk4 bs=2m</code> . 在左边的命令行里面<code>if</code> 和<code>of</code> 是输入和输出, <code>bs</code> 是块的大小, 和镜像读取速度有关, 但是也不能太大, <code>/dev/rdisk4</code> 里面多了一个<code>r</code> 是使用了U的原始读取模式, 没有使用缓存, 这样速度会更快</p><blockquote><p><em>写入需要花费几分钟时间，期间可以使用 CTRL + T 来查看写入进度</em></p></blockquote></li><li><p>上面命令执行完后, 使用命令 <code>diskutil eject</code> 弹出 U 盘, 进行后续步骤</p></li></ul></li></ul><ol start="3"><li>安装系统</li></ol><ul><li>根据主板的不同按相应的键进bois系统, 设置使用U盘启动</li><li>进去U盘启动页面后选择<code>Centos 7...</code> 的选项进行安装</li><li>进入安装页面 <ul><li>设置时间</li><li>设置网络</li><li>设置安装磁盘</li><li>设置安装模式(可以选择桌面模式)</li><li>设置完上面步骤后会进入按照流程, 在安装流程中可以设置默认用户和密码</li></ul></li><li>安装读条完毕, 拔掉U盘, 主机重启载入系统, 进行后续步骤</li></ul><h2 id="_2-获取免费域名-非必须" tabindex="-1">2. 获取免费域名(非必须) <a class="header-anchor" href="#_2-获取免费域名-非必须" aria-label="Permalink to &quot;2. 获取免费域名(非必须)&quot;">​</a></h2><p>这里使用了<code>freenom</code> 域名商提供的免费域名</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221203214500791.png" alt="image-20221203214500791"></p><ul><li>域名购买 <ul><li>检查意向域名有无被占用以及是否可以免费获取, 符合条件就可以点击<code>Get it now!</code> 按钮加入购物车进行登录购买(购买过程中需要进行登录和邮箱验证, 购买成功后有一定的延时)</li></ul></li></ul><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221203214640228.png" alt="image-20221203214640228"></p><ul><li><p>域名设置</p><ul><li>域名购买成功后进入箭头处的域名管理页面进行配置</li></ul><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221203215516544.png" alt="image-20221203215516544"></p><p>域名列表, 点击箭头处进行配置</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221203215649420.png" alt="image-20221203215649420"></p><p>设置dns(这里是和后续<code>Cloudflare</code> 配置使用的, 将域名的dns代理到<code>Cloudflare</code> 上)</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221203220009190.png" alt="image-20221203220009190"></p></li></ul><h2 id="_3-cloudflare配置" tabindex="-1">3. Cloudflare配置 <a class="header-anchor" href="#_3-cloudflare配置" aria-label="Permalink to &quot;3. Cloudflare配置&quot;">​</a></h2><ul><li>注册登录</li></ul><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221203222638693.png" alt="image-20221203222638693"></p><ul><li>配置站点, 将上一步获取的域名添加进来, 选择免费套餐, 然后将下面的服务器地址粘贴到到freenom的域名配置<code>Nameserver</code> 上</li></ul><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221203221314540.png" alt="image-20221203221314540"></p><p><code>Cloudflare</code> 的解析服务器</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221203223123106.png" alt="image-20221203223123106"></p><h2 id="_4-内网穿透-web和ssh" tabindex="-1">4. 内网穿透(web和ssh) <a class="header-anchor" href="#_4-内网穿透-web和ssh" aria-label="Permalink to &quot;4. 内网穿透(web和ssh)&quot;">​</a></h2><ol><li>服务端启动一个web服务</li></ol><p>启动该服务主要是为了验证后面是否可以在外网正常访问, 启动web服务有两种方式</p><ul><li>宝塔面板启动 <ul><li>在宝塔官网使用配置命令进行面板安装, 然后在站点处使用PHP新建一个站点, 端口可自行设置</li><li>设置站点后使用内网访问, 如果访问成功即部署成功, 可供后面进行内网穿透验证</li></ul></li><li>自行搭建 <ul><li>手动安装nginx或者docker启动nginx</li></ul></li></ul><ol start="2"><li>服务端安装<code>Cloudflare</code></li></ol><ul><li><p>首先进入root账户，能够获取root权限安装</p></li><li><p>配置yum-utils</p><ul><li><code>yum install yum-utils</code></li></ul></li><li><p>添加 <code>cloudflared.repo</code> 到 <code>config-manager</code></p><ul><li><code>yum-config-manager --add-repo https://pkg.cloudflare.com/cloudflared-ascii.repo</code></li></ul></li><li><p>安装 <code>cloudflared</code></p><ul><li><code>yum install cloudflared</code></li></ul></li></ul><ol start="3"><li>登录<code>Cloudflare</code></li></ol><ul><li>运行命令行登录 <ul><li>运行<code>cloudflared tunnel login</code></li></ul></li><li>验证 <ul><li>执行上面命令后会弹出来一个URL，用浏览器打开，登录成功后关闭浏览器，再次打开URL，这时候会出现授权页面，然后选择你想用来做内网穿透的域名授权即可。</li><li>成功后会生成证书，放置于<code>~/cloudflared/cert.pem</code>中。</li></ul></li></ul><ol start="4"><li>建立隧道</li></ol><ul><li><p>创建隧道(名字可以随意起)</p><ul><li>cloudflared tunnel create &lt;隧道名称&gt;</li><li>例子：<code>cloudflared tunnel create test</code></li><li>成功后会提示，相关凭证已放置于<code>~/.cloudflared/&lt;Tunnel-UUID&gt;.json</code>中。</li></ul></li><li><p>验证是否已经创建成功</p><ul><li><code>cloudflared tunnel list</code></li><li>该命令行会展示所有本机的隧道</li></ul></li></ul><ol start="5"><li>新建 Tunnel 对应的 DNS 记录, 在远端新增解析</li></ol><blockquote><p>成功后会创建CNAME记录将域名指向隧道，回到Cloudflare网站，点击域名，点击左边的DNS，能看到出现一条新的CNAME的DNS记录，此时证明解析成功</p></blockquote><ul><li>在远端增加dns解析 <ul><li>运行<code>cloudflared tunnel route dns &lt;隧道名称&gt; &lt;域名&gt;</code></li><li>例如: <code>cloudflared tunnel route dns test cloudfreed.tk</code></li></ul></li></ul><ol start="6"><li>新增配置文件</li></ol><ul><li>新增配置文件(包括普通web和ssh) <ul><li>运行<code>nano ~/.cloudflared/config.yml</code></li><li>添加下面代码(注意不要填错), 隧道ID是刚才创建的隧道id, 域名就是自己想要解析的域名</li></ul></li></ul><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tunnel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;隧道ID&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">credentials-file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/root/.cloudflared/&lt;隧道ID&gt;.json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http2</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">originRequest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> connectTimeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30s</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> noTLSVerify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ingress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">hostname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;域名&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 自己购买的域名</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:85</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 服务端启动web服务的端口</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">hostname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ssh.xxx.xxx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 这里是配置ssh的</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ssh://localhost:22</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http_status:404</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><blockquote><p>ssh服务推荐使用Zerotier进行搭建连接, 自己实测速度很快</p></blockquote><ul><li>注意如果是想使用ssh服务, 客户端也需要登录<code>cloudflare</code></li></ul><p>在客户端的ssh配置里面进行相应的配置, mac的为 <code>/etc/ssh/config</code> 添加下面配置</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host ssh.xxx.xxx</span></span>
<span class="line"><span>  ProxyCommand /opt/homebrew/bin/cloudflared access ssh --hostname %h</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>随后客户端ssh登录就可以使用 <code>ssh root@default.xxx.xxx </code>密码登录</p><ol start="7"><li>配置为系统服务且设置自启动</li></ol><ul><li>注册 <ul><li><code>cloudflared service install</code> 注册为系统服务</li></ul></li><li>自启动 <ul><li><code>systemctl enable cloudflared --now</code></li></ul></li><li>停止与修改配置 <ul><li>如果修改了配置项或者增加了新的解析映射, name就需要停止后重新启动</li><li>停止命令为<code>systemctl stop cloudflared</code></li><li>重新启动</li></ul></li></ul><ol start="8"><li>测试穿透 访问自己在上面配置的域名, 验证是否可以得到正常响应</li></ol><h2 id="补充-ssh相关" tabindex="-1">补充: SSH相关 <a class="header-anchor" href="#补充-ssh相关" aria-label="Permalink to &quot;补充: SSH相关&quot;">​</a></h2><ol><li>ssh连接服务端(以tabby为例)</li></ol><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204205427024.png" alt="image-20221204205427024"></p><p>使用tabby的时候可以配置Proxy command方式进行连接, 命令就是<code>4.6</code> 部分的<code>/opt/homebrew/bin/cloudflared access ssh --hostname &lt;你的ssh地址&gt;</code> 命令行</p><ol start="2"><li>Zerotier穿透</li></ol><blockquote><p>搭建流程可以在网上百度一下, 比较简单 <a href="https://blog.csdn.net/never_late/article/details/127329225" target="_blank" rel="noreferrer">https://blog.csdn.net/never_late/article/details/127329225</a><a href="https://baijiahao.baidu.com/s?id=1738840233744208152&amp;wfr=spider&amp;for=pc" target="_blank" rel="noreferrer">https://baijiahao.baidu.com/s?id=1738840233744208152&amp;wfr=spider&amp;for=pc</a></p></blockquote><p>经过自己测试, 发现使用Zerotier进行ssh连接速度十分快, 相比于cloudflared有了3倍多的提升, 下面是对比图 (补充: Zerotier速度快的原因是在一个局域网, 如果不在一个局域网, 且隧道两端不能直连, 访问速度也不会很快)</p><ul><li>cloudflared的延迟</li></ul><p>平均219ms</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221205165425151.png" alt="image-20221205165425151"></p><ul><li>Zerotier的延迟</li></ul><p>平均56ms的延迟</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221205165317433.png" alt="image-20221205165317433"></p><p>除此之外, 使用Zerotier穿透后可以直接用该ip在客户端访问服务器端其他端口服务, 如宝塔面板等</p><p>其他DDNS这种方案后续有需要了再研究下</p>`,66)])])}const g=s(t,[["render",n]]);export{u as __pageData,g as default};
